export interface GraphNode { id: string; label: string }
export function buildGraph(notes: Note[]) {
  const byTitle = new Map(notes.map((note) => [note.title, note]))
  const edges = notes.flatMap((note) => note.links.flatMap((link) => {
    const target = byTitle.get(link)
    return target ? [{ source: note.id, target: target.id }] : []
  }))
  return { nodes: notes.map((note) => ({ id: note.id, label: note.title })), edges }
}
